import { computed, onBeforeUnmount, watch, type Ref } from 'vue'
import * as THREE from 'three'
import type { EngineContext } from '@tencent/viewer-sdk'
import type { SelectionAABB } from '../../stores/scene'
// v1.2.0：sdk 层 v2.0.0 删除 getScene/getCamera/getDomElement 转发，改走 helper 走 ECS 直读
// v1.3.0：sceneManager.getFlyCameraController 已删除，改走同源 helper getSdkFlyCameraController（cameraModule.state.flyController 直读）
// v1.4.0：sceneManager.getCollisionManager 已删除（SceneManager v14.8.0），改走同源 helper getSdkCollisionMeshes（collisionModule.getCollisionMeshes 直读）
// v2.0.0：helper 签名改为 ctx 直传（sdkThreeContext v2.0.0）
import { getSdkThreeContext, getSdkFlyCameraController, getSdkCollisionMeshes } from '../../utils/sdkThreeContext'
// v2.0.0（thirdroom ctx 对齐）：useEngineContextGetter inject 拿 ctx
import { useEngineContextGetter } from '../useEngineContext'
import {
  BoundsHighlightRenderer,
  type HighlightLabel,
} from './bounds-highlight-renderer'
import {
  SelectionManager,
  type SelectionState,
} from './selection-manager'

export interface UseSelectionOptions {
  enabled: Ref<boolean>
  onCommitted?: (aabb: SelectionAABB) => void
  onStateChange?: (state: SelectionState) => void
}

export interface UseSelectionHandle {
  isReady: Readonly<Ref<boolean>>
  trySetup: () => boolean
  cancelSelection: () => void
  highlightAABB: (aabb: SelectionAABB, label: HighlightLabel) => void
  clearHighlight: () => void
  /** 运行时替换相机（正交/透视切换时调用），委托给 SelectionManager.setCamera */
  updateCamera: (camera: THREE.Camera) => void
}

export function useSelection(options: UseSelectionOptions): UseSelectionHandle {
  // v2.0.0：inject ctx getter，替代原 options.sdk 参数
  const getCtx = useEngineContextGetter()
  // v2.0.0：activeSdk 改为 activeCtx，跟踪 ctx 引用变化用于 cleanup 判定
  let activeCtx: EngineContext | null = null
  let selectionManager: SelectionManager | null = null
  let highlightRenderer: BoundsHighlightRenderer | null = null
  let flyCameraController: { setLookButton: (button: 'left' | 'right') => void } | null = null

  const isReady = computed(() => selectionManager !== null)

  function applyEnabled(enabled: boolean): void {
    if (flyCameraController) {
      flyCameraController.setLookButton(enabled ? 'right' : 'left')
    }
    selectionManager?.setEnabled(enabled)
  }

  function cleanup(): void {
    applyEnabled(false)
    selectionManager?.dispose()
    highlightRenderer?.dispose()
    selectionManager = null
    highlightRenderer = null
    flyCameraController = null
    activeCtx = null
  }

  function trySetup(): boolean {
    const ctx = getCtx()
    if (!ctx) return false

    if (activeCtx === ctx && selectionManager && highlightRenderer) {
      applyEnabled(options.enabled.value)
      return true
    }

    // v1.2.0：从 helper 一次拿三件套（ECS 直读 rendererModule/cameraModule state）
    // v2.0.0：helper 签名改为 ctx 直传
    const { camera, scene, domElement } = getSdkThreeContext(ctx)
    // v1.3.0：走 helper 走 ECS 直读 flyController（cameraModule.state.flyController，仅 Fly 档存在实例）
    // v2.0.0：helper 签名改为 ctx 直传
    const nextFlyCameraController = getSdkFlyCameraController(ctx)

    if (!camera || !scene || !domElement || !nextFlyCameraController) {
      return false
    }

    // 取 collision meshes，用于中心点 anchorY raycast（方案 D+）
    // v14.8.0：改走 helper `getSdkCollisionMeshes(ctx)`（sdkThreeContext.ts v1.2.0），
    //   内部 ECS 直读 `collisionModule.getCollisionMeshes(ctx)`；配套 SceneManager 删 getCollisionManager 转发 API
    // v2.0.0：helper 签名改为 ctx 直传
    const collisionMeshes = getSdkCollisionMeshes(ctx)

    cleanup()

    activeCtx = ctx
    flyCameraController = nextFlyCameraController
    selectionManager = new SelectionManager({
      camera,
      scene,
      domElement,
      collisionMeshes,
      onSelectionCommitted: options.onCommitted,
      onStateChange: options.onStateChange,
    })
    highlightRenderer = new BoundsHighlightRenderer({
      scene,
      camera,
    })

    applyEnabled(options.enabled.value)
    return true
  }

  function cancelSelection(): void {
    selectionManager?.cancelSelection()
  }

  function highlightAABB(aabb: SelectionAABB, label: HighlightLabel): void {
    highlightRenderer?.show(aabb, label)
  }

  function clearHighlight(): void {
    highlightRenderer?.hide()
  }

  function updateCamera(camera: THREE.Camera): void {
    selectionManager?.setCamera(camera)
  }

  // v2.0.0：watch 源从 `() => options.sdk.value` 改为 getCtx（返回最新 ctx）
  //   ctx 切换（场景切换 / teardown）时触发 cleanup
  watch(
    getCtx,
    (ctx, previousCtx) => {
      if (ctx !== previousCtx) {
        cleanup()
      }
    },
    { flush: 'sync' },
  )

  watch(
    () => options.enabled.value,
    (enabled) => {
      if (enabled && !selectionManager) {
        const didSetup = trySetup()
        if (!didSetup) return
      }
      applyEnabled(enabled)
    },
    { immediate: true, flush: 'sync' },
  )

  onBeforeUnmount(() => {
    cleanup()
  })

  return {
    isReady,
    trySetup,
    cancelSelection,
    highlightAABB,
    clearHighlight,
    updateCamera,
  }
}
