import * as THREE from 'three'
import type { SelectionAABB } from '../stores/scene'
import { type FaceIndex } from '../types/scene-config'

/**
 * Prop 正面朝向 4 面索引（从 types/scene-config.ts re-export）：
 * - 0 = OBB 本地 +Z 面（默认"正面"）
 * - 1 = OBB 本地 +X 面（"右"）
 * - 2 = OBB 本地 −Z 面（"后"）
 * - 3 = OBB 本地 −X 面（"左"）
 *
 * v5.0.0：rotation.y = obbDeg + faceIndex × 90°，faceIndex 折算进 rotationY 后
 * 渲染层蓝色面固定为本地 +Z（face 0）。
 */
export type { FaceIndex }

/**
 * 正俯视判定阈值：相机视线 XZ 分量长度小于此值视为正俯视。
 * 经验值 1e-6：相机几乎完全朝下时，frontWorld 投影到 XZ 平面后趋于 0 向量，
 * 此时 |localX| 与 |localZ| 都接近噪声，判面不稳定 → 走 fallback。
 */
const TOP_DOWN_EPSILON = 1e-6

/**
 * 计算默认正面索引：选择"最朝向相机"的那一面。
 *
 * 算法（tech-design §3.4.1）：
 *   1. camDir = camera.getWorldDirection()  // 已归一化
 *   2. frontWorld = (-camDir.x, 0, -camDir.z)  // 物体正面应面向相机
 *      若长度 < ε（正俯视）→ 返回 face 0（RISK-DA002 fallback）
 *      否则 normalize
 *   3. 反旋转 OBB.rotationY 转换到本地系：
 *      localX =  frontWorld.x * cos(-θ) - frontWorld.z * sin(-θ) =  fx*cos(θ) + fz*sin(θ)
 *      localZ =  frontWorld.x * sin(-θ) + frontWorld.z * cos(-θ) = -fx*sin(θ) + fz*cos(θ)
 *   4. 比较 |localX| vs |localZ|：
 *        |localZ| ≥ |localX| → +Z 主导：localZ ≥ 0 ? face 0 : face 2
 *        否则             → +X 主导：localX ≥ 0 ? face 1 : face 3
 */
export function computeDefaultFaceIndex(
  camera: THREE.PerspectiveCamera,
  obb: SelectionAABB,
): FaceIndex {
  const camDir = new THREE.Vector3()
  camera.getWorldDirection(camDir) // 单位向量

  // 物体正面应面向相机：法线 ≈ -camDir，投影到 XZ 平面
  const fx = -camDir.x
  const fz = -camDir.z
  const lenXZ = Math.hypot(fx, fz)

  // 正俯视退化（相机几乎完全朝下/朝上）：返回确定性 fallback face 0
  if (lenXZ < TOP_DOWN_EPSILON) return 0

  // 归一化（避免后续点积量级失真，虽然只比较相对大小但仍保持稳定性）
  const fxn = fx / lenXZ
  const fzn = fz / lenXZ

  // 反旋转 OBB.rotationY → 转到 OBB 本地系
  const theta = obb.rotationY ?? 0
  const cosT = Math.cos(theta)
  const sinT = Math.sin(theta)
  const localX = fxn * cosT + fzn * sinT
  const localZ = -fxn * sinT + fzn * cosT

  if (Math.abs(localZ) >= Math.abs(localX)) {
    return localZ >= 0 ? 0 : 2 // +Z / -Z
  }
  return localX >= 0 ? 1 : 3 // +X / -X
}


