<script setup lang="ts">
import { ref, computed } from 'vue'
import { useSceneStore } from '../../stores/scene'

const emit = defineEmits<{
  (e: 'open-scene-url'): void
  (e: 'export-config'): void
  (e: 'import-config'): void
  (e: 'load-recent-url', url: string): void
  (e: 'restart-onboarding'): void
}>()

const sceneStore = useSceneStore()
const isSceneActive = computed(() => sceneStore.sdkSceneUrl !== null)
const canExport = computed(() => sceneStore.canExportConfig)
const recentUrls = computed(() => sceneStore.recentUrls)

/**
 * 菜单项类型：
 * - separator: 分隔线
 * - submenu: 二级菜单容器（hover 展开右侧子菜单）
 * - 普通项: label + action（可选 shortcut / disabled / tooltip）
 *
 * v3.0.0 后仅保留 3 个真功能 action：open-scene-url / close-scene / export-config
 * 以及 1 个二级菜单：最近文件
 */
type MenuItem =
  | { type: 'separator' }
  | {
      type: 'submenu'
      label: string
      /** 子项列表；空时显示 emptyLabel 作为禁用提示 */
      children: Array<{ label: string; action: 'load-recent-url'; payload: string }>
      emptyLabel: string
    }
  | {
      label: string
      shortcut?: string
      action: 'open-scene-url' | 'close-scene' | 'import-config' | 'export-config' | 'restart-onboarding'
      disabled?: boolean
      tooltip?: string
    }

const menus = computed<Array<{ label: string; items: MenuItem[] }>>(() => [
  {
    label: '文件',
    items: [
      { label: '打开场景 URL', shortcut: 'Ctrl+O', action: 'open-scene-url' },
      {
        label: '关闭场景',
        action: 'close-scene',
        disabled: !isSceneActive.value,
      },
      { type: 'separator' },
      // 导入 / 导出 成对的逆操作（v3.1.0）
      // 导入需要场景已加载（v3.2.0）：scene-config 的 floor/prop 坐标依赖高斯场景做位置参考，
      // 没加载底图就导入纯数据，用户看不到也校不准，空中楼阁
      {
        label: '导入场景配置',
        action: 'import-config',
        disabled: !isSceneActive.value,
        tooltip: isSceneActive.value
          ? ''
          : '请先加载场景（文件 → 打开场景 URL...）',
      },
      {
        label: '导出场景配置',
        shortcut: 'Ctrl+S',
        action: 'export-config',
        disabled: !canExport.value,
        tooltip: canExport.value
          ? ''
          : '请先录入场景信息或新增至少一个对象/地面',
      },
      { type: 'separator' },
      {
        type: 'submenu',
        label: '最近文件',
        emptyLabel: '（暂无）',
        children: recentUrls.value.map((url) => ({
          label: url,
          action: 'load-recent-url' as const,
          payload: url,
        })),
      },
    ],
  },
  {
    label: '帮助',
    items: [
      { label: '重新引导', action: 'restart-onboarding' },
    ],
  },
])

const openMenu = ref<number | null>(null)
const openSubmenu = ref<number | null>(null) // 当前展开的二级菜单 item 索引

function toggleMenu(idx: number) {
  openMenu.value = openMenu.value === idx ? null : idx
  openSubmenu.value = null
}

function closeAll() {
  openMenu.value = null
  openSubmenu.value = null
}

/**
 * 鼠标进入某一级菜单项时：
 * - 普通项：收起任何已打开的二级菜单
 * - 二级菜单项：展开它（hover 即展开，符合常见桌面菜单约定）
 */
function onItemEnter(iidx: number, item: MenuItem) {
  if ('type' in item && item.type === 'submenu') {
    openSubmenu.value = iidx
  } else {
    openSubmenu.value = null
  }
}

function onItemClick(item: MenuItem) {
  if ('type' in item) {
    // separator / submenu 自身不响应 click（submenu 通过 hover 展开）
    return
  }
  if (item.disabled) return
  closeAll()
  if (item.action === 'open-scene-url') {
    emit('open-scene-url')
  } else if (item.action === 'close-scene') {
    sceneStore.unloadScene()
  } else if (item.action === 'import-config') {
    emit('import-config')
  } else if (item.action === 'export-config') {
    emit('export-config')
  } else if (item.action === 'restart-onboarding') {
    emit('restart-onboarding')
  }
}

function onSubmenuItemClick(child: { action: 'load-recent-url'; payload: string }) {
  closeAll()
  if (child.action === 'load-recent-url') {
    emit('load-recent-url', child.payload)
  }
}

/**
 * 截断显示长 URL：保留协议头 + 末尾文件名段，中间用 … 省略。
 * 桌面菜单宽度有限，完整 URL 可塞进 title 里给 hover tooltip。
 */
function shortUrl(url: string, max = 56): string {
  if (url.length <= max) return url
  const head = url.slice(0, Math.floor(max * 0.55))
  const tail = url.slice(-Math.floor(max * 0.4))
  return `${head}…${tail}`
}
</script>

<template>
  <header
    class="flex items-center h-9 bg-[#1a1a1d] border-b border-border shrink-0 z-50 no-select"
    data-tour="menu-file"
    @mouseleave="closeAll"
  >
    <!-- Logo -->
    <div class="flex items-center gap-2 px-3 mr-1">
      <img src="/splat-studio-logo.svg" alt="SplatStudio" class="w-5 h-5" />
      <span class="text-xs font-bold text-text-primary tracking-wide">SplatStudio</span>
    </div>

    <!-- Menu items -->
    <nav class="flex items-center h-full">
      <div
        v-for="(menu, idx) in menus"
        :key="idx"
        class="relative h-full"
        :data-tour="menu.label === '帮助' ? 'menu-help' : undefined"
      >
        <button
          :class="[
            'h-full px-3 text-xs font-medium transition-colors cursor-pointer',
            openMenu === idx
              ? 'bg-accent text-white'
              : 'text-text-secondary hover:bg-bg-hover hover:text-text-primary active:bg-bg-active',
          ]"
          @click="toggleMenu(idx)"
          @mouseenter="openMenu !== null ? (openMenu = idx) : undefined"
        >
          {{ menu.label }}
        </button>

        <!-- Dropdown -->
        <div
          v-if="openMenu === idx"
          class="absolute top-full left-0 min-w-[240px] py-1 bg-[#242428] border border-border-strong
                 rounded-md shadow-dropdown z-50"
        >
          <template v-for="(item, iidx) in menu.items" :key="iidx">
            <!-- Separator -->
            <div
              v-if="'type' in item && item.type === 'separator'"
              class="h-px my-1 mx-2 bg-border"
            />

            <!-- Submenu trigger -->
            <div
              v-else-if="'type' in item && item.type === 'submenu'"
              class="relative"
              @mouseenter="onItemEnter(iidx, item)"
            >
              <button
                class="flex items-center justify-between w-full px-3 h-7 text-xs transition-colors
                       text-text-primary hover:bg-accent hover:text-white cursor-default"
              >
                <span>{{ item.label }}</span>
                <span class="text-2xs text-text-subtle ml-6">▶</span>
              </button>

              <!-- Submenu panel -->
              <div
                v-if="openSubmenu === iidx"
                class="absolute top-0 left-full ml-px min-w-[280px] max-w-[480px] py-1
                       bg-[#242428] border border-border-strong rounded-md shadow-dropdown z-50"
              >
                <template v-if="item.children.length === 0">
                  <div class="px-3 h-7 flex items-center text-xs text-text-subtle italic">
                    {{ item.emptyLabel }}
                  </div>
                </template>
                <template v-else>
                  <button
                    v-for="(child, cidx) in item.children"
                    :key="cidx"
                    class="flex w-full px-3 h-7 text-xs items-center text-text-primary
                           hover:bg-accent hover:text-white cursor-pointer truncate text-left"
                    :title="child.label"
                    @click="onSubmenuItemClick(child)"
                  >
                    <span class="truncate font-mono">{{ shortUrl(child.label) }}</span>
                  </button>
                </template>
              </div>
            </div>

            <!-- Normal item -->
            <button
              v-else
              :class="[
                'flex items-center justify-between w-full px-3 h-7 text-xs transition-colors',
                item.disabled
                  ? 'text-text-subtle cursor-not-allowed opacity-60'
                  : 'text-text-primary hover:bg-accent hover:text-white active:bg-accent-hover cursor-pointer',
              ]"
              :disabled="item.disabled"
              :title="item.tooltip || ''"
              @mouseenter="onItemEnter(iidx, item)"
              @click="onItemClick(item)"
            >
              <span>{{ item.label }}</span>
              <span v-if="item.shortcut" class="text-2xs text-text-subtle font-mono ml-6">
                {{ item.shortcut }}
              </span>
            </button>
          </template>
        </div>
      </div>
    </nav>
  </header>
</template>
