<script setup lang="ts">
import { computed } from 'vue'
import { IconGlobe, IconLocked, IconMove, IconRotate, IconScale } from '../../utils/icons'
import { useEditorStore } from '../../stores/editor'
import { useSceneStore } from '../../stores/scene'
import type { ToolType } from '../../types/editor'
import { formatSavedAt } from '../../utils/draftStorage'

const sceneStore = useSceneStore()
const editorStore = useEditorStore()

/* ============================================================
 * 左侧选中态展示（v2.0.0）
 *
 * 数据源切换：旧 selectedObject（来自 selectObject() 通路）已死，
 * 改读 selectedConfigKey + sceneConfig.floor/prop —— 这是实际驱动
 * HierarchyPanel / InspectorPanel 选中高亮的同一份真值。
 *
 * 显示规则：
 *   - kind: 'meta'  → "场景信息"
 *   - kind: 'floor' → 找到 floor 项，显示其 name（找不到则降级为 id）
 *   - kind: 'prop'  → 同上
 *   - null         → "未选中对象"
 *
 * 未来若要 meta 节点（只读 SDK 节点）选中也展示，可补 selectedObjectId 分支。
 * ============================================================ */
type SelectedDisplay =
  | { kind: 'floor' | 'prop'; name: string }
  | { kind: 'meta'; name: string }
  | null

const selectedDisplay = computed<SelectedDisplay>(() => {
  const key = sceneStore.selectedConfigKey
  if (!key) return null

  if (key.kind === 'meta') {
    return { kind: 'meta', name: '场景信息' }
  }

  if (key.kind === 'floor') {
    const floor = sceneStore.sceneConfig.floor.find((f) => f.id === key.id)
    return { kind: 'floor', name: floor?.name ?? key.id }
  }

  // key.kind === 'prop'
  const prop = sceneStore.sceneConfig.prop.find((p) => p.id === key.id)
  return { kind: 'prop', name: prop?.name ?? key.id }
})

const floorCount = computed(() => sceneStore.sceneConfig.floor.length)
const propCount = computed(() => sceneStore.sceneConfig.prop.length)

/* ============================================================
 * 右侧三元组徽标（v2.1.0）— 单向读 editorStore
 *
 * 数据链路：editorStore.activeTool / axisLock / transformSpace
 *   → 计算展示对象 { icon, label, dim? }
 *   → 渲染：[图标 + 文字] 胶囊
 *
 * 设计原则（EV-012 单一事实源）：
 *   · 零交互（不触发任何 action）
 *   · 不做任何状态本地缓存，全部 computed 派生
 * ============================================================ */

type ToolBadge = { icon: typeof IconMove; label: string } | null

/**
 * 模式徽标：仅 translate/rotate/scale 三种编辑模式显示；
 * select/region-select 等非变换模式下返回 null（整个徽标不渲染）。
 */
const toolBadge = computed<ToolBadge>(() => {
  const map: Record<ToolType, ToolBadge> = {
    move: { icon: IconMove, label: '移动' },
    rotate: { icon: IconRotate, label: '旋转' },
    scale: { icon: IconScale, label: '缩放' },
    select: null,
    'region-select': null,
  }
  return map[editorStore.activeTool]
})

/**
 * 轴锁徽标文本："X" / "Y" / "Z" / "—"（占位）。
 * 未锁时仍渲染（dimmed），占位避免左右抖动 —— 符合 §3.5.3 视觉要求。
 */
const axisLockLabel = computed(() => editorStore.axisLock ?? '—')
const axisLockDim = computed(() => editorStore.axisLock === null)

const spaceLabel = computed(() => (editorStore.transformSpace === 'world' ? '世界' : '本地'))

/* ============================================================
 * v2.2.0 业务约束视觉反馈
 *
 * 在 rotate / scale 模式下，坐标系切换与轴锁存在业务/库层面的约束：
 *   · rotate：prop 业务锁死 rotation.x=z=0，local Y ≡ world Y（切换坐标系视觉无效）；
 *             轴锁也只支持 Y（X/Z 已在 store 层拒绝）
 *   · scale：three r169 TransformControls 源码硬编码 scale 强制 local（切换坐标系视觉无效）
 *
 * 视觉处理：dim（opacity-40）+ tooltip 文案改写，告知用户"不是 bug，是业务/库限制"。
 * 对应 store 层（editor.ts v1.1.0）的 toggleAxisLock / toggleTransformSpace 守卫。
 * ============================================================ */

/** 坐标系徽标是否 dim（rotate/scale 下切换视觉无效） */
const spaceBadgeDim = computed(
  () => editorStore.activeTool === 'rotate' || editorStore.activeTool === 'scale',
)

/** 坐标系徽标 tooltip 文案（按模式差异化） */
const spaceBadgeTitle = computed(() => {
  if (editorStore.activeTool === 'rotate') {
    return `坐标系：${spaceLabel.value}（当前模式仅支持 Y 轴旋转，世界/本地等价）`
  }
  if (editorStore.activeTool === 'scale') {
    return `坐标系：${spaceLabel.value}（缩放强制使用本地坐标系，Three.js 内部限制）`
  }
  return `坐标系：${spaceLabel.value}（Backquote 切换）`
})

/** 轴锁徽标 tooltip（rotate 下补充"仅支持 Y 轴"说明） */
const axisLockTitle = computed(() => {
  if (editorStore.activeTool === 'rotate') {
    return editorStore.axisLock
      ? `轴锁：${editorStore.axisLock}（当前模式仅支持 Y 轴）`
      : '未锁轴（当前模式仅支持 Y 轴旋转）'
  }
  return editorStore.axisLock ? `轴锁：${editorStore.axisLock}` : '未锁轴'
})
</script>

<template>
  <footer class="flex items-center h-7 bg-[#1a1a1d] border-t border-border shrink-0 z-50 px-3 no-select">
    <!-- Left: 创建意图（最高优先级） → 选中对象 → 未选中 -->
    <div class="flex-1 flex items-center gap-2 text-2xs text-text-muted truncate">
      <!-- v1.0.0: 创建意图进行中（覆盖所有其他显示） -->
      <template v-if="sceneStore.pendingCreateKind !== null">
        <span class="inline-block w-1.5 h-1.5 rounded-full bg-accent animate-pulse shrink-0" />
        <span class="text-accent font-medium">
          正在新增{{ sceneStore.pendingCreateKind === 'floor' ? '地面' : '对象' }}
        </span>
        <span class="text-text-subtle">· ESC 取消</span>
      </template>
      <!-- 已选中对象（v2.0.0：基于 selectedConfigKey） -->
      <template v-else-if="selectedDisplay">
        <span
          :class="[
            'px-1.5 py-0.5 rounded text-2xs font-semibold',
            selectedDisplay.kind === 'floor'
              ? 'bg-type-floor/20 text-type-floor'
              : selectedDisplay.kind === 'prop'
                ? 'bg-type-prop/20 text-type-prop'
                : 'bg-bg-hover text-text-secondary',
          ]"
        >
          {{ selectedDisplay.kind }}
        </span>
        <span class="text-text-secondary truncate">{{ selectedDisplay.name }}</span>
      </template>
      <span v-else class="text-text-subtle">未选中对象</span>
    </div>

    <!-- Divider -->
    <div class="w-px h-3.5 bg-border mx-3" />

    <!-- Center: scene stats（v2.0.0：拆成 地面 / 对象 两个独立计数，反映 sceneConfig 真值） -->
    <div class="flex items-center gap-4 text-2xs text-text-muted">
      <span>地面: <span class="text-text-secondary font-medium">{{ floorCount }}</span></span>
      <span>对象: <span class="text-text-secondary font-medium">{{ propCount }}</span></span>
    </div>

    <!-- Divider -->
    <div class="w-px h-3.5 bg-border mx-3" />

    <!-- Right: editor state（v2.1.0：三元组徽标 — 模式/轴锁/坐标系，常驻） -->
    <div class="flex-1 flex items-center justify-end gap-2 text-xs">
      <!-- v2.3.0：草稿存档时间（有存档时显示，告知用户数据安全） -->
      <span
        v-if="sceneStore.lastDraftSavedAt !== null"
        class="text-2xs text-text-subtle"
        title="标注数据已自动存档到本地，刷新后可恢复"
      >
        已存档 {{ formatSavedAt(sceneStore.lastDraftSavedAt) }}
      </span>
      <!-- 模式徽标（select 等非变换模式下隐藏） -->
      <span
        v-if="toolBadge"
        class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-gray-800/60 text-text-secondary"
        :title="`当前变换模式：${toolBadge.label}`"
      >
        <component :is="toolBadge.icon" :size="12" />
        <span>{{ toolBadge.label }}</span>
      </span>

      <!-- 轴锁徽标（未锁时 opacity-40 + — 占位，避免抖动） -->
      <span
        class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-gray-800/60 transition-opacity"
        :class="axisLockDim ? 'opacity-40 text-text-muted' : 'text-accent'"
        :title="axisLockTitle"
      >
        <IconLocked :size="12" />
        <span class="font-mono">{{ axisLockLabel }}</span>
      </span>

      <!-- 坐标系徽标（rotate/scale 下 dim：local ≡ world / three 库限制） -->
      <span
        class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-gray-800/60 transition-opacity"
        :class="spaceBadgeDim ? 'opacity-40 text-text-muted' : 'text-text-secondary'"
        :title="spaceBadgeTitle"
      >
        <IconGlobe :size="12" />
        <span>{{ spaceLabel }}</span>
      </span>

      <span class="font-mono text-text-subtle ml-1">SplatStudio v0.1</span>
    </div>
  </footer>
</template>
