import { onMounted, onUnmounted } from 'vue'
import { useEditorStore } from '../stores/editor'
import { SHORTCUTS, TRANSFORM_TOOLS } from '../constants/shortcuts'
import { toast } from './useToast'
import { isEditableTarget } from '../utils/keyboard'

/* ================================================================
 * v1.2.1 业务守卫 toast 去重抑制
 *
 * 场景：用户在 rotate 模式下按 X（或长按后 e.repeat 已被屏蔽，仍可能手动连按），
 *   每次 keydown 都 toast.warning 会在 ToastHost 堆叠 N 条相同消息，反而更烦。
 *
 * 策略：模块级 <message, lastTimestamp> 缓存，同一消息 2 秒内只弹一次；不同消息互不抑制
 *   （rotate 下先按 X 再按 Backquote 会得到两条不同 warning）。
 *
 * 为什么不用 Set/Map：仅 2~3 种固定消息，简单对象开销最小；也不需要清理过期条目（重写覆盖即可）。
 * ================================================================ */
const WARN_SUPPRESS_MS = 2000
const lastWarnAt: Record<string, number> = Object.create(null)

function warnOnce(message: string): void {
  const now = Date.now()
  if (now - (lastWarnAt[message] ?? 0) < WARN_SUPPRESS_MS) return
  lastWarnAt[message] = now
  toast.warning(message)
}

/**
 * 挂载全局变换快捷键监听器。
 * 典型用法：在 SplatStudio.vue 的 setup 顶层调用一次。
 *
 * 与 SplatStudio 既有 `handleGlobalKeyDown` 的共存策略：
 *   - 两个 handler 都挂在 window 上，按注册顺序触发。
 *   - Escape：本 handler 仅在 `editor.axisLock !== null` 时消费
 *     （preventDefault + stopPropagation，避免冒泡到 SplatStudio 的 region-select 双档退出）；
 *     若无轴锁则完全透传，保证原有 ESC 语义不变。
 *   - 其他按键（G/R/T/X/Y/Z/Backquote）SplatStudio 均未监听，无冲突。
 */
export function useTransformShortcuts(): void {
  const editor = useEditorStore()

  function onKeyDown(e: KeyboardEvent): void {
    // 守卫 1：修饰键（保留浏览器 / 编辑器组合键）
    if (e.ctrlKey || e.metaKey || e.altKey) return
    // 守卫 2+3：可编辑元素
    if (isEditableTarget(e.target)) return

    switch (e.code) {
      case SHORTCUTS.MODE_TRANSLATE:
        editor.setTool('move')
        e.preventDefault()
        return
      case SHORTCUTS.MODE_ROTATE:
        editor.setTool('rotate')
        e.preventDefault()
        return
      case SHORTCUTS.MODE_SCALE:
        editor.setTool('scale')
        e.preventDefault()
        return

      case SHORTCUTS.AXIS_X:
      case SHORTCUTS.AXIS_Y:
      case SHORTCUTS.AXIS_Z: {
        // 屏蔽 OS 键盘自动重复（长按 X/Y/Z 每 30~50ms 重复触发 keydown，会让 toggle 语义
        // 的轴锁快速闪切；Set 语义的 G/R/T 不受此影响，故只在 toggle 分支过滤）
        if (e.repeat) return
        // 轴锁仅在三变换模式下响应（select / region-select 静默，避免误切换时突兀锁轴）
        if (!TRANSFORM_TOOLS.has(editor.activeTool as 'move' | 'rotate' | 'scale')) return
        const axis =
          e.code === SHORTCUTS.AXIS_X ? 'X' : e.code === SHORTCUTS.AXIS_Y ? 'Y' : 'Z'
        // v1.2.0 业务守卫：rotate 模式下只允许锁 Y —— prop 业务约束 rotation.x=z=0，
        // 锁 X/Z 会让 Gizmo 所有手柄消失（lockAllowY=false），形成死按钮。
        // preventDefault 仍保留：避免 X/Z 透传给 SDK FlyCamera 或浏览器默认动作。
        // v1.2.1：静默 → toast.warning 告知用户为什么不响应（含 2s 去重）
        if (editor.activeTool === 'rotate' && axis !== 'Y') {
          warnOnce('当前模式仅支持 Y 轴旋转')
          e.preventDefault()
          return
        }
        editor.toggleAxisLock(axis)
        e.preventDefault()
        return
      }

      case SHORTCUTS.SPACE_TOGGLE:
        // 同 toggle 语义：屏蔽长按 Backquote 导致 world/local 疯狂闪切及 localStorage 抖动
        if (e.repeat) return
        // v1.2.0 业务守卫：rotate（local Y ≡ world Y）/ scale（three r169 强制 local）
        // 模式下切换视觉无效，消费避免死按钮反馈（StatusBar 徽标变字但 Gizmo 不动）。
        // v1.2.1：差异化 toast.warning 告知原因（含 2s 去重）
        if (editor.activeTool === 'rotate') {
          warnOnce('当前模式仅支持 Y 轴旋转，世界/本地坐标系等价')
          e.preventDefault()
          return
        }
        if (editor.activeTool === 'scale') {
          warnOnce('缩放强制使用本地坐标系（Three.js 限制）')
          e.preventDefault()
          return
        }
        editor.toggleTransformSpace()
        e.preventDefault()
        return

      case SHORTCUTS.ESCAPE:
        // 有轴锁 → 消费并清除；无轴锁 → 完全透传（让 SplatStudio 处理 region-select 退出等）
        if (editor.axisLock !== null) {
          editor.clearAxisLock()
          e.preventDefault()
          e.stopPropagation()
        }
        return

      default:
        return
    }
  }

  onMounted(() => {
    window.addEventListener('keydown', onKeyDown)
  })

  onUnmounted(() => {
    window.removeEventListener('keydown', onKeyDown)
  })
}
