import { currentContext } from './current-context';
import { hostRegistry } from './host-registry';
import type { IProgramContext } from './types';

/**
 * 获取当前活跃 program 的 context
 *
 * 每次属性访问时调用，确保多 program 之间的隔离性。
 * 如果当前没有活跃 program（不在 init/dispose/call 生命周期内），抛出异常。
 */
function getCurrentContext(): IProgramContext {
  const id = currentContext.active();
  if (!id) {
    throw new Error(
      '[program-host] 没有活跃的 program context，请在 program.init() 生命周期内访问 host。',
    );
  }
  const ctx = hostRegistry.get(id);
  if (!ctx) {
    throw new Error(
      `[program-host] program "${id}" 的 context 未注册到 hostRegistry。`,
    );
  }
  return ctx;
}

/**
 * 创建 host 代理对象
 *
 * 每次属性访问通过 getCurrentContext() 获取当前活跃 program 的 context，
 * 确保多 program 场景下的隔离性。
 *
 * 特殊处理：
 * - `registerApi` — 自动 bind 所有回调到当前 program 上下文
 * - `program()` — 不需要 bind，因为调用时 SDK 会自行 enter 目标上下文
 */
function createHostProxy(): IProgramContext {
  // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
  const proxy = new Proxy({} as IProgramContext, {
    get(_target, prop) {
      const ctx = getCurrentContext();

      // registerApi: 自动 bind 所有回调到当前 program 上下文
      if (prop === 'registerApi') {
        const id = currentContext.active()!;
        return (methods: Record<string, (...args: unknown[]) => unknown>) => {
          const boundMethods: Record<string, (...args: unknown[]) => unknown> = {};
          for (const [key, fn] of Object.entries(methods)) {
            boundMethods[key] = currentContext.bind(id, fn);
          }
          ctx.registerApi(boundMethods);
        };
      }

      return (ctx as unknown as Record<string, unknown>)[prop as string];
    },
  });

  return proxy;
}

/**
 * 创建绑定到指定 program 的 host 代理
 *
 * 与单例 host 不同，bound host 在每次属性访问时自动 enter/leave 指定 program 的上下文，
 * 而不依赖全局 currentContext.active()。这使得异步回调（setInterval、Vue watcher 等）
 * 也能正确路由到对应 program 的 context。
 *
 * 用于 UMD bundle 沙箱场景：createRealm 时捕获 programId，之后所有访问都绑定到该 program。
 */
export function createBoundHost(programId: string): IProgramContext {
  // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
  const proxy = new Proxy({} as IProgramContext, {
    get(_target, prop) {
      currentContext.enter(programId);
      try {
        const ctx = hostRegistry.get(programId);
        if (!ctx) {
          throw new Error(
            `[program-host] program "${programId}" 的 context 未注册到 hostRegistry。`,
          );
        }

        // registerApi: 自动 bind 所有回调到当前 program 上下文
        if (prop === 'registerApi') {
          return (methods: Record<string, (...args: unknown[]) => unknown>) => {
            const boundMethods: Record<string, (...args: unknown[]) => unknown> = {};
            for (const [key, fn] of Object.entries(methods)) {
              boundMethods[key] = currentContext.bind(programId, fn);
            }
            ctx.registerApi(boundMethods);
          };
        }

        return (ctx as unknown as Record<string, unknown>)[prop as string];
      } finally {
        currentContext.leave();
      }
    },
  });
  return proxy;
}

/** host 单例 — program 中通过 `import host from '@tencent/program-host'` 获取 */
export const host: IProgramContext = createHostProxy();
