/**
 * SelectionManager — 框选交互主控
 *
 * 管理框选交互的完整生命周期：监听 pointer 事件、计算 2D 拖拽矩形、
 * 投影到视觉平面、计算 XZ AABB，并通过回调通知宿主。
 *
 * 方案 D+（v1.1.0）：
 *   - X/Z 仍走平面投影（绝对稳定，不会 XZ 爆炸）
 *   - Y 由拖框中心点单次 collision raycast 确定 anchorY（贴中心点视觉表面）
 *   - anchorY 未命中时退化到 groundY，再未命中退化到 0
 *   - 全程只 1 次 raycast，性能影响可忽略
 *
 * <!-- @changelog -->
 * <table>
 *   <tr><th>版本</th><th>变更说明</th><th>关联</th></tr>
 *   <tr>
 *     <td>v1.0.0</td>
 *     <td>从 viewer-sdk 迁移 SelectionManager 到 H5 本地 useSelection 模块</td>
 *     <td>REQ: 20260427-框选迁移H5<br/>TECH: 04_design_tech-design.md §3.4.5</td>
 *   </tr>
 *   <tr>
 *     <td>v1.1.0</td>
 *     <td>方案 D+：中心点单次 collision raycast 取 anchorY，X/Z 走 Y=anchorY 平面投影；从根本上消除多采样点跨 y 层导致的 AABB 爆炸问题</td>
 *     <td>REQ: 框选贴视觉平面<br/>TECH: 方案D+分析</td>
 *   </tr>
 *   <tr>
 *     <td>v1.2.0</td>
 *     <td>computeAABB → computeOBB：投影 2D 矩形 4 角到 XZ 平面，用"上边"方向确定 rotationY，输出带朝向的 OBB；3D 线框 X 轴方向与用户拖拽 2D 线框平行</td>
 *     <td>REQ: 3D线框与2D线框方向一致<br/>TECH: OBB框选方案</td>
 *   </tr>
 * </table>
 * <!-- /@changelog -->
 *
 * @author v_djlzhou
 */
import * as THREE from 'three'
import type { SelectionAABB } from '../../stores/scene'
import { BoundsHighlightRenderer } from './bounds-highlight-renderer'
import { SelectionOverlay } from './selection-overlay'

export type SelectionState = 'idle' | 'dragging' | 'committed'

export interface SelectionManagerOptions {
  camera: THREE.Camera
  scene: THREE.Scene
  domElement: HTMLElement
  /** collision GLB 的 Three.js Mesh 列表，用于中心点 raycast 取 anchorY */
  collisionMeshes?: THREE.Object3D[]
  /** 场景整体地面 Y（collision 未命中时的 fallback） */
  groundY?: number
  onSelectionCommitted?: (aabb: SelectionAABB) => void
  onStateChange?: (state: SelectionState) => void
}

const MAX_PROJECTION_DISTANCE = 1000
const MIN_SELECTION_AREA = 0.01
/** anchorY 上方保留的可视余量（让高亮框顶部高出表面 2m） */
const AABB_HEIGHT_ABOVE = 2
/** anchorY 下方保留的穿透余量（让高亮框底部略低于表面 0.05m，避免 z-fighting） */
const AABB_HEIGHT_BELOW = 0.05

export class SelectionManager {
  private camera: THREE.Camera
  private scene: THREE.Scene
  private domElement: HTMLElement
  private enabled = false
  private collisionMeshes: THREE.Object3D[]
  private groundY: number

  private state: SelectionState = 'idle'
  private dragStartScreen: THREE.Vector2 | null = null
  private dragEndScreen: THREE.Vector2 | null = null

  private raycaster: THREE.Raycaster
  private currentAABB: SelectionAABB | null = null

  private overlay: SelectionOverlay
  private highlightRenderer: BoundsHighlightRenderer

  private boundOnPointerDown: (event: PointerEvent) => void
  private boundOnPointerMove: (event: PointerEvent) => void
  private boundOnPointerUp: (event: PointerEvent) => void
  private boundOnContextMenu: (event: Event) => void

  private onSelectionCommitted?: (aabb: SelectionAABB) => void
  private onStateChange?: (state: SelectionState) => void

  constructor(options: SelectionManagerOptions) {
    this.camera = options.camera
    this.scene = options.scene
    this.domElement = options.domElement
    this.collisionMeshes = options.collisionMeshes ?? []
    this.groundY = options.groundY ?? 0
    this.onSelectionCommitted = options.onSelectionCommitted
    this.onStateChange = options.onStateChange

    this.raycaster = new THREE.Raycaster()

    const container = this.domElement.parentElement ?? this.domElement
    this.overlay = new SelectionOverlay(container)
    this.highlightRenderer = new BoundsHighlightRenderer({
      scene: this.scene,
      camera: this.camera,
    })

    this.boundOnPointerDown = this.onPointerDown.bind(this)
    this.boundOnPointerMove = this.onPointerMove.bind(this)
    this.boundOnPointerUp = this.onPointerUp.bind(this)
    this.boundOnContextMenu = (event: Event) => event.preventDefault()
  }

  /** 启用或禁用框选模式 */
  setEnabled(enabled: boolean): void {
    if (enabled === this.enabled) return
    this.enabled = enabled

    if (enabled) {
      this.domElement.addEventListener('pointerdown', this.boundOnPointerDown)
      this.domElement.addEventListener('pointermove', this.boundOnPointerMove)
      this.domElement.addEventListener('pointerup', this.boundOnPointerUp)
      this.domElement.addEventListener('contextmenu', this.boundOnContextMenu)
      return
    }

    this.domElement.removeEventListener('pointerdown', this.boundOnPointerDown)
    this.domElement.removeEventListener('pointermove', this.boundOnPointerMove)
    this.domElement.removeEventListener('pointerup', this.boundOnPointerUp)
    this.domElement.removeEventListener('contextmenu', this.boundOnContextMenu)
    this.cancelSelection()
  }

  /** 运行时替换相机（正交/透视切换时调用） */
  setCamera(camera: THREE.Camera): void {
    this.camera = camera
  }

  /** 获取当前选中 AABB */
  getCurrentAABB(): SelectionAABB | null {
    return this.currentAABB
  }

  /** 获取当前状态 */
  getState(): SelectionState {
    return this.state
  }

  /** 取消当前选区并清空所有视觉状态 */
  cancelSelection(): void {
    this.setState('idle')
    this.dragStartScreen = null
    this.dragEndScreen = null
    this.currentAABB = null
    this.overlay.hide()
    this.highlightRenderer.hide()
  }

  /** 确认选中后清空当前无标签高亮 */
  commitSelection(): void {
    this.setState('idle')
    this.currentAABB = null
    this.highlightRenderer.hide()
    this.overlay.hide()
  }

  /** 每帧更新占位，保留扩展口 */
  update(): void {
    // no-op
  }

  /** 销毁资源 */
  dispose(): void {
    this.setEnabled(false)
    this.overlay.dispose()
    this.highlightRenderer.dispose()
  }

  /**
   * 对屏幕坐标发射射线，与 collision meshes 求交，取第一个法线朝上（dot>0.5）的命中点 y。
   * 未命中或无 collision meshes 时返回 null（调用方退化到 groundY）。
   */
  private rayCastAnchorY(screenX: number, screenY: number): number | null {
    if (this.collisionMeshes.length === 0) return null

    const rect = this.domElement.getBoundingClientRect()
    const ndcX = ((screenX - rect.left) / rect.width) * 2 - 1
    const ndcY = -((screenY - rect.top) / rect.height) * 2 + 1

    this.raycaster.setFromCamera(new THREE.Vector2(ndcX, ndcY), this.camera)
    const hits = this.raycaster.intersectObjects(this.collisionMeshes, true)

    for (const hit of hits) {
      if (!hit.face) continue
      // 法线需要转换到世界空间再判断是否朝上
      const worldNormal = hit.face.normal
        .clone()
        .applyMatrix3(
          new THREE.Matrix3().getNormalMatrix(hit.object.matrixWorld),
        )
        .normalize()
      if (worldNormal.y > 0.5) {
        return hit.point.y
      }
    }
    return null
  }

  /**
   * 将屏幕坐标投影到 Y=anchorY 的水平面，返回世界坐标。
   * 投影距离超过 MAX_PROJECTION_DISTANCE 时返回 null。
   */
  private screenToPlane(screenX: number, screenY: number, anchorY: number): THREE.Vector3 | null {
    const rect = this.domElement.getBoundingClientRect()
    const ndcX = ((screenX - rect.left) / rect.width) * 2 - 1
    const ndcY = -((screenY - rect.top) / rect.height) * 2 + 1

    this.raycaster.setFromCamera(new THREE.Vector2(ndcX, ndcY), this.camera)

    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -anchorY)
    const intersection = new THREE.Vector3()
    const hit = this.raycaster.ray.intersectPlane(plane, intersection)
    if (!hit) return null

    if (intersection.distanceTo(this.camera.position) > MAX_PROJECTION_DISTANCE) {
      return null
    }

    return intersection
  }

  /**
   * 将 2D 拖拽矩形的 4 角投影到 Y=anchorY 平面，计算 OBB（有向包围盒）。
   *
   * 算法：
   * 1. 投影 TL/TR/BL/BR 4 个屏幕角点到 XZ 平面
   * 2. 用"上边"投影方向（TR - TL）作为 OBB 本地 X 轴（dirX）
   * 3. rotationY = -atan2(dirX.z, dirX.x)（Three.js Y 轴旋转约定）
   * 4. 将 4 点投影到 dirX/dirZ 坐标系，求 halfExtents 与 center
   * 5. 输出 SelectionAABB（minX/maxX/minZ/maxZ 为本地坐标系 center ± halfExtents）
   *
   * 正俯视时 dirX ≈ 世界 +X，rotationY ≈ 0，退化为轴对齐 AABB（无 regression）。
   */
  private computeOBB(
    start: THREE.Vector2,
    end: THREE.Vector2,
    anchorY: number,
  ): SelectionAABB | null {
    // 2D 矩形 4 角投影到 XZ 平面
    const pTL = this.screenToPlane(start.x, start.y, anchorY) // Top-Left
    const pTR = this.screenToPlane(end.x, start.y, anchorY)   // Top-Right
    const pBL = this.screenToPlane(start.x, end.y, anchorY)   // Bottom-Left
    const pBR = this.screenToPlane(end.x, end.y, anchorY)     // Bottom-Right

    if (!pTL || !pTR || !pBL || !pBR) return null

    // "上边" TL→TR 的投影方向 = OBB 本地 X 轴
    const dirX = new THREE.Vector2(pTR.x - pTL.x, pTR.z - pTL.z)
    const dirLen = dirX.length()
    if (dirLen < 1e-6) return null
    dirX.divideScalar(dirLen) // normalize

    // 垂直方向（XZ 平面内旋转 90°）= OBB 本地 Z 轴
    const dirZ = new THREE.Vector2(-dirX.y, dirX.x)

    // Three.js rotation.y：绕 Y 轴，从 +X 逆时针旋转为正
    // dirX 表示 OBB 本地 X 轴在世界 XZ 中的方向（x 对应世界X, y 对应世界Z）
    // rotation.y = -atan2(dirX.z, dirX.x)
    const rotationY = -Math.atan2(dirX.y, dirX.x)

    // 4 点的世界坐标重心
    const cx = (pTL.x + pTR.x + pBL.x + pBR.x) / 4
    const cz = (pTL.z + pTR.z + pBL.z + pBR.z) / 4

    // 将 4 点投影到 dirX / dirZ 坐标轴，求各轴 min/max
    const points = [pTL, pTR, pBL, pBR]
    let minU = Infinity, maxU = -Infinity
    let minV = Infinity, maxV = -Infinity
    for (const p of points) {
      const dx = p.x - cx
      const dz = p.z - cz
      const u = dx * dirX.x + dz * dirX.y
      const v = dx * dirZ.x + dz * dirZ.y
      if (u < minU) minU = u
      if (u > maxU) maxU = u
      if (v < minV) minV = v
      if (v > maxV) maxV = v
    }

    const halfW = (maxU - minU) / 2
    const halfD = (maxV - minV) / 2

    // OBB 中心（考虑透视梯形下 4 点可能不完全对称）
    const localCenterU = (minU + maxU) / 2
    const localCenterV = (minV + maxV) / 2
    const worldCenterX = cx + localCenterU * dirX.x + localCenterV * dirZ.x
    const worldCenterZ = cz + localCenterU * dirX.y + localCenterV * dirZ.y

    return {
      minX: worldCenterX - halfW,
      maxX: worldCenterX + halfW,
      minZ: worldCenterZ - halfD,
      maxZ: worldCenterZ + halfD,
      minY: anchorY - AABB_HEIGHT_BELOW,
      maxY: anchorY + AABB_HEIGHT_ABOVE,
      rotationY,
    }
  }

  private onPointerDown(event: PointerEvent): void {
    if (!this.enabled) return
    if (event.button !== 0) return
    if (this.state === 'committed') return

    event.preventDefault()

    this.setState('dragging')
    this.dragStartScreen = new THREE.Vector2(event.clientX, event.clientY)
    this.dragEndScreen = new THREE.Vector2(event.clientX, event.clientY)
    this.currentAABB = null
    this.highlightRenderer.hide()
  }

  private onPointerMove(event: PointerEvent): void {
    if (!this.enabled || this.state !== 'dragging' || !this.dragStartScreen) return

    this.dragEndScreen = new THREE.Vector2(event.clientX, event.clientY)
    this.overlay.show(
      this.dragStartScreen.x,
      this.dragStartScreen.y,
      this.dragEndScreen.x,
      this.dragEndScreen.y,
    )

    // 方案 D+：用拖框中心点单次 raycast 取 anchorY，再将 2D 矩形 4 角投影到 Y=anchorY 平面，计算 OBB
    const centerX = (this.dragStartScreen.x + this.dragEndScreen.x) / 2
    const centerY = (this.dragStartScreen.y + this.dragEndScreen.y) / 2
    const anchorY = this.rayCastAnchorY(centerX, centerY) ?? this.groundY

    const obb = this.computeOBB(this.dragStartScreen, this.dragEndScreen, anchorY)

    if (obb) {
      this.currentAABB = obb
      this.highlightRenderer.show(this.currentAABB, 'unlabeled')
      return
    }

    this.highlightRenderer.hide()
    this.currentAABB = null
  }

  private onPointerUp(event: PointerEvent): void {
    if (!this.enabled || this.state !== 'dragging') return
    if (event.button !== 0) return

    this.overlay.hide()

    if (!this.currentAABB) {
      this.cancelSelection()
      return
    }

    const area =
      (this.currentAABB.maxX - this.currentAABB.minX) *
      (this.currentAABB.maxZ - this.currentAABB.minZ)
    if (area < MIN_SELECTION_AREA) {
      this.cancelSelection()
      return
    }

    this.setState('committed')
    this.highlightRenderer.show(this.currentAABB, 'unlabeled')
    this.onSelectionCommitted?.(this.currentAABB)
  }

  private setState(next: SelectionState): void {
    if (this.state === next) return
    this.state = next
    this.onStateChange?.(next)
  }
}
