import type { IProgramContext } from './types';

/** 全局注册表：programId → IProgramContext */
const registry = new Map<string, IProgramContext>();

export const hostRegistry = {
  /** SDK 侧调用：注册 program context */
  register(id: string, context: IProgramContext): void {
    registry.set(id, context);
  },

  /** SDK 侧调用：注销 program context */
  unregister(id: string): void {
    registry.delete(id);
  },

  /** host 内部调用：获取指定 program 的 context */
  get(id: string): IProgramContext | undefined {
    return registry.get(id);
  },

  /** 销毁整个注册表 */
  dispose(): void {
    registry.clear();
  },
};
