export const SHORTCUTS = {
  /** 移动模式（Blender 习惯 G）*/
  MODE_TRANSLATE: 'KeyG',
  /** 旋转模式（Blender 习惯 R）*/
  MODE_ROTATE: 'KeyR',
  /** 缩放模式（避让 FlyCamera S 后退键 → T = Transform-scale）*/
  MODE_SCALE: 'KeyT',
  /** 轴锁 X */
  AXIS_X: 'KeyX',
  /** 轴锁 Y */
  AXIS_Y: 'KeyY',
  /** 轴锁 Z */
  AXIS_Z: 'KeyZ',
  /** 坐标系切换（反引号 `，Tab 被浏览器焦点占用）*/
  SPACE_TOGGLE: 'Backquote',
  /** 解除轴锁 / 退出框选 */
  ESCAPE: 'Escape',

  /* ---------- Blender 正交视角（小键盘） ---------- */
  /** Numpad 7 → Top 视角 */
  VIEW_TOP: 'Numpad7',
  /** Numpad 1 → Front 视角 */
  VIEW_FRONT: 'Numpad1',
  /** Numpad 3 → Right 视角 */
  VIEW_RIGHT: 'Numpad3',
  // Ctrl+Numpad 7/1/3 → Bottom/Back/Left 反向视角：
  // 与无 Ctrl 版共享同一物理码（Numpad7/1/3），由 useViewShortcuts 内 e.ctrlKey 三元分发，
  // 不单独定义常量（值重复无法独立消费，反而误导维护者）。
  /** Numpad 5 → 切回 Perspective */
  VIEW_PERSPECTIVE: 'Numpad5',
} as const

export type ShortcutCode = (typeof SHORTCUTS)[keyof typeof SHORTCUTS]

/** 仅在这些工具激活时响应轴锁快捷键（select / region-select 静默）*/
export const TRANSFORM_TOOLS = new Set<'move' | 'rotate' | 'scale'>([
  'move',
  'rotate',
  'scale',
])
