<script setup lang="ts">
import * as THREE from 'three'
import { useEditorStore } from '../../stores/editor'
import type { CameraMode } from '../../types/editor'
import AxesGizmo from './AxesGizmo.vue'
import AxisLockToast from './AxisLockToast.vue'
import FacePickingHint from './FacePickingHint.vue'

defineProps<{
  /**
   * 由 Viewport.vue 注入：返回当前活动相机的四元数（无论 SceneEngine 还是 ViewerSDK）。
   * 没有可用相机时返回 null，AxesGizmo 自行处理（保持上一帧）。
   */
  getCameraQuaternion: () => THREE.Quaternion | null
}>()

const editorStore = useEditorStore()

function onViewChange(mode: CameraMode): void {
  editorStore.setCameraMode(mode)
}
</script>

<template>
  <div class="absolute inset-0 pointer-events-none z-10">
    <!-- Top-center: camera mode badge（已注释，按需启用） -->
    <!-- <div class="absolute top-3 left-1/2 -translate-x-1/2 flex items-center gap-1.5
                px-3 py-1 rounded-md bg-[#1a1a1d] border border-border text-2xs">
      <div class="w-1.5 h-1.5 rounded-full bg-accent"></div>
      <span class="text-text-secondary font-medium">{{ editorStore.cameraMode }}</span>
    </div> -->

    <!-- Bottom-left: 跟随相机姿态的 3 轴方向指示；点击轴球可切换正交视角 -->
    <AxesGizmo
      :get-camera-quaternion="getCameraQuaternion"
      :active-mode="editorStore.cameraMode"
      @view-change="onViewChange"
    />

    <!-- Top-center: 轴锁 / 模式切换瞬时反馈（Blender 风格 toast，pointer-none 不拦截鼠标） -->
    <AxisLockToast />

    <!-- Top-center: face-pick 工具激活时的操作提示（REQ 20260508） -->
    <FacePickingHint />

    <!--
      v3.2.1：scale 锁轴拖拽虚线不再由本组件承接 —— useModalAxisDrag 内部命令式创建
      SVG 挂到 Viewport 容器，零响应式延迟（见 useModalAxisDrag v1.2.1 changelog）
    -->
  </div>
</template>
