import type { Command, EditableEntitySnapshot } from '../types/command'
import type { useSceneStore } from '../stores/scene'

/**
 * 快照替换命令：用完整快照进行替换，支持 id 变更。
 *
 * undo 时用 after.id 定位 → 替换成 before
 * redo 时用 before.id 定位 → 替换成 after
 *
 * 用于：Inspector 修改字段、Gizmo 拖拽、旋转 90 度、数值输入修改等。
 */
export class ReplaceEntityCommand implements Command {
  readonly label: string

  constructor(
    private readonly sceneStore: ReturnType<typeof useSceneStore>,
    private readonly before: EditableEntitySnapshot,
    private readonly after: EditableEntitySnapshot,
    label?: string,
  ) {
    if (before.kind !== after.kind) {
      throw new Error(
        `ReplaceEntityCommand: kind mismatch (before=${before.kind}, after=${after.kind}). Cross-kind replacement is not supported.`,
      )
    }
    this.label = label ?? `编辑 ${before.data.id}`
  }

  execute(): boolean {
    if (this.after.kind === 'floor') {
      return this.sceneStore.replaceFloorSnapshot(this.before.data.id, this.after.data)
    }
    return this.sceneStore.replacePropSnapshot(this.before.data.id, this.after.data)
  }

  undo(): boolean {
    if (this.before.kind === 'floor') {
      return this.sceneStore.replaceFloorSnapshot(this.after.data.id, this.before.data)
    }
    return this.sceneStore.replacePropSnapshot(this.after.data.id, this.before.data)
  }
}
